
CREATE TABLE IF NOT EXISTS payouts (id INT PRIMARY KEY AUTO_INCREMENT,seller_id CHAR(36) NOT NULL,amount DECIMAL(10,2) NOT NULL,status ENUM('PENDING','PROCESSED','REJECTED') NOT NULL DEFAULT 'PENDING',bank_details TEXT NOT NULL,processed_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(seller_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS seller_applications (id INT PRIMARY KEY AUTO_INCREMENT,user_id CHAR(36) NOT NULL,store_name VARCHAR(255) NOT NULL,description TEXT NULL,category VARCHAR(100) NULL,phone VARCHAR(50) NULL,status ENUM('PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'PENDING',admin_note TEXT NULL,reviewed_by CHAR(36) NULL,reviewed_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS banners (id INT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(255) NULL,subtitle TEXT NULL,image_url VARCHAR(500) NOT NULL,link_url VARCHAR(500) NULL,is_active TINYINT NOT NULL DEFAULT 1,position VARCHAR(30) NOT NULL DEFAULT 'hero',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS curated_edits (id INT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(255) NOT NULL,subtitle TEXT NULL,price DECIMAL(10,2) NOT NULL DEFAULT 0,item_count VARCHAR(100) NULL,image_url VARCHAR(500) NOT NULL,link_url VARCHAR(500) NULL,size ENUM('LARGE','SMALL') NOT NULL DEFAULT 'SMALL',is_active TINYINT NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
